from pathlib import Path
import base64, binascii, re, yaml
for path in sorted(Path('.github/workflows').glob('*.y*ml')):
    raw=path.read_text(encoding='utf-8').strip()
    compact=re.sub(r'\s+', '', raw)
    is_b64=len(compact)%4==0 and bool(re.fullmatch(r'[A-Za-z0-9+/=]+', compact))
    if is_b64:
        try:
            decoded=base64.b64decode(compact, validate=True).decode('utf-8')
            yaml.safe_load(decoded)
            print(f'BASE64_VALID_YAML {path} decoded_bytes={len(decoded.encode())} first={decoded.splitlines()[0]!r}')
        except (binascii.Error, UnicodeDecodeError, yaml.YAMLError) as exc:
            print(f'BASE64_INVALID {path}: {exc}')
    else:
        print(f'PLAIN_YAML {path}')
